281:   consultar(plan: ResumenPlan | any) {
282:     this.request.get(environment.OIKOS_SERVICE, `dependencia_tipo_dependencia?query=DependenciaId:` + plan.dependencia_id).subscribe((dataUnidad: any) => {
283:       this.request.get(environment.PARAMETROS_SERVICE, `periodo?query=Id:` + plan.vigencia_id).subscribe((dataVigencia: any) => {
284:         if (plan.fase.includes('Formulación')) {
285:           this.serviceCookies.setCookie("plan", JSON.stringify(plan));
286:           this.serviceCookies.setCookie("vigencia", JSON.stringify(dataVigencia.Data[0]));
287:           this.serviceCookies.setCookie("unidad", JSON.stringify(dataUnidad[0]['DependenciaId']));
288:           singleSpa.navigateToUrl(`/formulacion/`);
289: 
