233:     public getAuthorizationUrl() {
234:         this.params = this.environment;
235:         if (!this.params.hasOwnProperty('nonce')) {
236:             const nonceData = this.generateState();
237:             this.params = { ...this.params, ...{ nonce: nonceData } };
238:         }
239:         if (!this.params.state) {
240:             this.params.state = this.generateState();
241:         }
242:         let url = this.params.AUTORIZATION_URL + '?' +
243:             'client_id=' + encodeURIComponent(this.params.CLIENTE_ID) + '&' +
244:             'redirect_uri=' + encodeURIComponent(this.params.REDIRECT_URL) + '&' + // + window.location.href + '&' para redirect con regex
245:             'response_type=' + encodeURIComponent(this.params.RESPONSE_TYPE) + '&' +
246:             'scope=' + encodeURIComponent(this.params.SCOPE) + '&' +
247:             'state_url=' + encodeURIComponent(window.location.hash);
248:         if (this.params.hasOwnProperty('nonce')) {
249:             url += '&nonce=' + encodeURIComponent(this.params.nonce);
250:         }
251:         url += '&state=' + encodeURIComponent(this.params.state);
252:         window.location.replace(url);
253:         return url;
254:     }
255: 
256:     public generateState(): any {
257:         const text = ((Date.now() + Math.random()) * Math.random()).toString().replace('.', '');
258:         return Md5.hashStr(text);
259:     }
