261:     public setExpiresAt(): any {
262:         const expiresAt = localStorage.getItem('expires_at');
263:         if (!expiresAt || expiresAt === 'Invalid Date') {
264:             const expiresAtDate = new Date();
265:             expiresAtDate.setSeconds(expiresAtDate.getSeconds() + parseInt(window.localStorage.getItem('expires_in'), 10));
266:             window.localStorage.setItem('expires_at', new Date(expiresAtDate).toUTCString());
267:             return new Date(expiresAtDate);
268:         } else {
269:             return expiresAt === 'Invalid Date' ? false : new Date(expiresAt);
270:         }
271:     }
