282:                 const timerDelay = expiresIn > this.timeLogoutBefore ? expiresIn - this.timeLogoutBefore : this.timeLogoutBefore;
283:                 if (!isNaN(expiresIn)) {
284:                     console.log(`%cFecha expiración: %c${new Date(expires)}`, 'color: blue', 'color: green');
